<style>
  :root {
    --ink: #1a1410;
    --parchment: #f5f0e8;
    --gold: #b8912a;
    --gold-light: #d4aa4a;
    --ash: #5a5450;
    --rule: #c8b89a;
    --white: #faf7f2;
    --sky: #2a5a8c;
  }

  *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
  html { scroll-behavior: smooth; }

  body {
    background: var(--parchment);
    color: var(--ink);
    font-family: 'Cormorant Garamond', Georgia, serif;
    font-size: 18px;
    line-height: 1.7;
    overflow-x: hidden;
  }

  /* NAV */
  nav {
    position: sticky;
    top: 0;
    z-index: 100;
    background: rgba(26,20,16,0.96);
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0.9rem 2rem;
    gap: 1rem;
    flex-wrap: wrap;
  }

  .nav-brand {
    font-family: 'Cormorant Garamond', serif;
    font-size: 1rem;
    font-weight: 300;
    color: var(--parchment);
    letter-spacing: 0.04em;
    text-decoration: none;
  }

  .nav-brand em { color: var(--gold); font-style: italic; }

  .nav-links {
    display: flex;
    gap: 1.5rem;
    flex-wrap: wrap;
    align-items: center;
  }

  .nav-links a {
    font-family: 'DM Mono', monospace;
    font-size: 0.65rem;
