      rgba(245,240,232,0.15) 0%,
      rgba(245,240,232,0.35) 60%,
      rgba(245,240,232,0.92) 100%
    );
  }

  .hero-content {
    position: relative;
    z-index: 1;
    max-width: 780px;
  }

  .hero-eyebrow {
    font-family: 'DM Mono', monospace;
    font-size: 0.72rem;
    letter-spacing: 0.25em;
