  }

  .hero h1 em {
    font-style: italic;
    color: var(--gold);
  }

  .hero h1 .sky-line {
    color: var(--sky);
    display: block;
  }

  .hero-rule {
    width: 48px;
    height: 1px;
    background: var(--gold);
