  }

  .hero p {
    font-size: clamp(1rem, 2vw, 1.25rem);
    font-style: italic;
    font-weight: 300;
    color: var(--ash);
    max-width: 560px;
    margin: 0 auto 2.5rem;
    line-height: 1.8;
  }

  .hero-cta {
    display: inline-block;
    font-family: 'DM Mono', monospace;
    font-size: 0.72rem;
    letter-spacing: 0.2em;
    text-transform: uppercase;
    background: var(--ink);
    color: var(--parchment);
    padding: 1rem 2.5rem;
    text-decoration: none;
    transition: background 0.2s;
  }

  .hero-cta:hover { background: var(--gold); color: var(--ink); }

  /* SCRIPTURE BAND */
  .scripture-band {
    background: var(--ink);
    color: var(--parchment);
    text-align: center;
    padding: 3rem 2rem;
  }

  .scripture-band blockquote {
    font-size: clamp(1rem, 2.5vw, 1.4rem);
    font-style: italic;
    font-weight: 300;
    max-width: 700px;
    margin: 0 auto;
    line-height: 1.75;
  }

  .scripture-band cite {
    display: block;
    margin-top: 1rem;
    font-family: 'DM Mono', monospace;
    font-size: 0.68rem;
    letter-spacing: 0.18em;
    text-transform: uppercase;
    font-style: normal;
    color: var(--gold);
  }

  /* SECTIONS */
  .section {
    max-width: 960px;
    margin: 0 auto;
    padding: 5rem 2rem;
    border-bottom: 1px solid var(--rule);
  }

  .section:last-of-type { border-bottom: none; }

  .section-label {
    font-family: 'DM Mono', monospace;
    font-size: 0.68rem;
    letter-spacing: 0.22em;
    text-transform: uppercase;
    color: var(--gold);
    margin-bottom: 1.5rem;
    display: flex;
    align-items: center;
    gap: 1rem;
  }

  .section-label::after {
    content: '';
    flex: 1;
    height: 1px;
    background: var(--rule);
    max-width: 180px;
  }

  .section-title {
    font-size: clamp(1.5rem, 3.5vw, 2.4rem);
    font-weight: 300;
    line-height: 1.3;
    margin-bottom: 1.5rem;
  }

  .section-title em { color: var(--gold); font-style: italic; }

  .body-text {
    color: var(--ash);
    font-size: 1.05rem;
    line-height: 1.9;
    font-weight: 300;
    max-width: 660px;
  }

  .body-text + .body-text { margin-top: 1.25rem; }

  /* IMAGE SPLIT */
  .split {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 3rem;
    align-items: center;
    margin-top: 3rem;
  }

  .split img {
    width: 100%;
    height: 320px;
    object-fit: cover;
    object-position: center;
  }

  .split-text { padding: 1rem 0; }

  /* PILLARS */
  .pillars {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 1.5rem;
    margin-top: 3rem;
  }

  .pillar {
    padding: 2rem 1.5rem;
    border: 1px solid var(--rule);
    background: var(--white);
    transition: border-color 0.2s, transform 0.2s;
  }

  .pillar:hover {
    border-color: var(--gold);
    transform: translateY(-3px);
  }

  .pillar-icon {
    font-size: 1.5rem;
    margin-bottom: 1rem;
    display: block;
    color: var(--gold);
  }

  .pillar h3 {
    font-size: 1.05rem;
    font-weight: 600;
    letter-spacing: 0.03em;
    margin-bottom: 0.6rem;
  }

  .pillar p {
    font-size: 0.9rem;
    color: var(--ash);
    font-weight: 300;
    line-height: 1.75;
  }

  /* CERTIFICATIONS */
  .cert-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
    gap: 1.5rem;
    margin-top: 3rem;
  }

  .cert-card {
    border: 1px solid var(--rule);
    background: var(--white);
    padding: 2rem;
    transition: border-color 0.2s;
  }

  .cert-card:hover { border-color: var(--gold); }

  .cert-provider {
    font-family: 'DM Mono', monospace;
    font-size: 0.65rem;
    letter-spacing: 0.18em;
    text-transform: uppercase;
    color: var(--gold);
    margin-bottom: 0.75rem;
  }

  .cert-card h3 {
    font-size: 1.1rem;
    font-weight: 600;
    margin-bottom: 0.5rem;
  }

  .cert-card p {
    font-size: 0.88rem;
    color: var(--ash);
    font-weight: 300;
    line-height: 1.7;
    margin-bottom: 1.25rem;
  }

  .cert-link {
    font-family: 'DM Mono', monospace;
    font-size: 0.68rem;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    color: var(--gold);
    text-decoration: none;
    border-bottom: 1px solid var(--gold-light);
    padding-bottom: 1px;
    transition: color 0.2s, border-color 0.2s;
  }

  .cert-link:hover { color: var(--ink); border-color: var(--ink); }

  /* CONTACT FORM */
  .contact-section {
    background: var(--ink);
    color: var(--parchment);
    padding: 5rem 2rem;
  }

  .contact-inner {
    max-width: 640px;
    margin: 0 auto;
  }

  .contact-inner .section-label { color: var(--gold); }
  .contact-inner .section-label::after { background: #3a3028; }

  .contact-inner .section-title { color: var(--parchment); }

  .contact-inner .body-text {
    color: #a09888;
    margin-bottom: 2.5rem;
  }

  .form-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 1rem;
    margin-bottom: 1rem;
  }

  .form-group {
    display: flex;
    flex-direction: column;
    margin-bottom: 1rem;
  }

  .form-group label {
    font-family: 'DM Mono', monospace;
    font-size: 0.65rem;
    letter-spacing: 0.16em;
    text-transform: uppercase;
    color: #a09888;
    margin-bottom: 0.4rem;
  }

  .form-group input,
  .form-group select,
  .form-group textarea {
    background: #2a2018;
    border: 1px solid #3a3028;
    color: var(--parchment);
    font-family: 'Cormorant Garamond', serif;
    font-size: 1rem;
    font-weight: 300;
    padding: 0.75rem 1rem;
    outline: none;
    transition: border-color 0.2s;
    -webkit-appearance: none;
  }

  .form-group input:focus,
  .form-group select:focus,
  .form-group textarea:focus {
    border-color: var(--gold);
  }

  .form-group select option { background: #2a2018; }

  .form-group textarea {
    resize: vertical;
    min-height: 120px;
  }

  .form-submit {
    font-family: 'DM Mono', monospace;
    font-size: 0.72rem;
    letter-spacing: 0.2em;
    text-transform: uppercase;
    background: var(--gold);
    color: var(--ink);
    border: none;
    padding: 1rem 2.5rem;
    cursor: pointer;
    transition: background 0.2s;
    margin-top: 0.5rem;
  }

  .form-submit:hover { background: var(--gold-light); }

  /* FOOTER */
  footer {
    background: #0e0c0a;
    color: #6b6460;
    text-align: center;
    padding: 3rem 2rem;
  }

  .footer-name {
    font-family: 'Cormorant Garamond', serif;
    font-size: 1.1rem;
    font-weight: 300;
    letter-spacing: 0.08em;
    color: var(--parchment);
    margin-bottom: 0.4rem;
  }

  .footer-name em { color: var(--gold); font-style: italic; }

  .footer-mono {
    font-family: 'DM Mono', monospace;
    font-size: 0.62rem;
    letter-spacing: 0.18em;
    text-transform: uppercase;
    color: var(--gold);
    margin-bottom: 1.5rem;
  }

  footer p {
    font-size: 0.8rem;
    line-height: 1.7;
    max-width: 480px;
    margin: 0 auto;
  }

  footer a { color: var(--gold-light); text-decoration: none; }
  footer a:hover { color: var(--parchment); }

  /* SCROLL FADE */
  .fade-up {
    opacity: 0;
    transform: translateY(20px);
    transition: opacity 0.7s ease, transform 0.7s ease;
  }

  .fade-up.visible {
    opacity: 1;
    transform: translateY(0);
  }

  /* RESPONSIVE */
  @media (max-width: 700px) {
    .split { grid-template-columns: 1fr; }
    .form-row { grid-template-columns: 1fr; }
    .pillars { grid-template-columns: 1fr 1fr; }
    .cert-grid { grid-template-columns: 1fr; }
    nav { padding: 0.75rem 1rem; }
  }

  @media (max-width: 480px) {
    .pillars { grid-template-columns: 1fr; }
  }
</style>
</head>
<body>

<!-- NAV -->
<nav>
  <a href="#" class="nav-brand">The <em>Thessalonian</em> Mandate Institute</a>
  <div class="nav-links">
    <a href="#mission">Mission</a>
    <a href="#support">Support</a>
    <a href="#certifications">Certifications</a>
    <a href="#apply">Apply</a>
    <a href="#apply" class="nav-apply">Apply Free</a>
  </div>
</nav>

<!-- HERO -->
<section class="hero">
  <div class="hero-bg"></div>
  <div class="hero-content">
    <div class="hero-eyebrow">Faith &nbsp;&#183;&nbsp; Work &nbsp;&#183;&nbsp; Community</div>
    <h1>
      You were made to <em>work.</em>
      <span class="sky-line">We will equip you.</span>
    </h1>
    <div class="hero-rule"></div>
    <p>Free, industry-recognized certifications for displaced workers &#8212; supported by a community that understands the road.</p>
    <a href="#apply" class="hero-cta">Begin Your Journey</a>
  </div>
</section>

<!-- SCRIPTURE -->
<div class="scripture-band">
  <blockquote>
    &#8220;Make it your ambition to lead a quiet life, to mind your own affairs, and to work with your hands &#8212; so that you will not be dependent on anybody.&#8221;
  </blockquote>
  <cite>1 Thessalonians 4:11</cite>
</div>

<!-- MISSION -->
<div class="section fade-up" id="mission">
  <div class="section-label">Our Purpose</div>
  <h2 class="section-title">The <em>Mandate</em></h2>
  <div class="split">
    <img src="shepherd.png" alt="A shepherd leading workers toward a modern church on a hill">
    <div class="split-text">
      <p class="body-text">
        When technology displaced the work that sustained your life, your dignity did not change. Your value did not change. Only the tools did.
      </p>
      <p class="body-text" style="margin-top:1.25rem;">
        TMI exists to bridge that gap. We are not a school. We are a faith-based support network that connects displaced workers with free certification programs from IBM, Google, and Microsoft &#8212; and walks with you every step of the way.
      </p>
      <p class="body-text" style="margin-top:1.25rem;">
        Not as instructors. As a community that holds the same faith, the same struggle, and the same determination to see you through.
      </p>
    </div>
  </div>
</div>

<!-- SUPPORT PILLARS -->
<div class="section fade-up" id="support">
  <div class="section-label">How We Walk With You</div>
  <h2 class="section-title">Four <em>Pillars</em> of Support</h2>
  <div class="pillars">
    <div class="pillar">
      <span class="pillar-icon">&#10022;</span>
      <h3>Faith Support</h3>
      <p>Prayer, scripture, and community. Your worth is not contingent on your employment status. We hold that truth with you when it is hard to hold alone.</p>
    </div>
    <div class="pillar">
      <span class="pillar-icon">&#9670;</span>
      <h3>Study Support</h3>
      <p>Accountability partners, study groups, and help navigating free certification platforms. You do not have to figure out the coursework by yourself.</p>
    </div>
    <div class="pillar">
      <span class="pillar-icon">&#9671;</span>
      <h3>Emotional Support</h3>
      <p>Displacement is a loss. We do not rush past that. We sit with you in it and move forward together when you are ready.</p>
    </div>
    <div class="pillar">
      <span class="pillar-icon">&#9633;</span>
      <h3>Job Placement</h3>
      <p>Resume help, interview preparation, and connections to employers actively hiring people with the certifications we help you earn.</p>
    </div>
  </div>
</div>

<!-- CERTIFICATIONS -->
<div class="section fade-up" id="certifications">
  <div class="section-label">Free Pathways</div>
  <h2 class="section-title">Industry-Recognized <em>Certifications</em></h2>
  <p class="body-text">
    The companies that built the technology that changed your industry offer free certification programs. We help you find them, navigate them, and complete them.
  </p>
  <div class="cert-grid">
    <div class="cert-card">
      <div class="cert-provider">IBM</div>
      <h3>IBM SkillsBuild</h3>
      <p>Free courses in AI, cybersecurity, cloud computing, and data science &#8212; with IBM-recognized credentials and pathways to employment.</p>
      <a href="https://skillsbuild.org" target="_blank" rel="noopener" class="cert-link">skillsbuild.org &#8599;</a>
    </div>
    <div class="cert-card">
      <div class="cert-provider">Google</div>
      <h3>Google Career Certificates</h3>
      <p>Professional certificates in IT support, data analytics, UX design, project management, and cybersecurity. No experience required.</p>
      <a href="https://grow.google/certificates" target="_blank" rel="noopener" class="cert-link">grow.google/certificates &#8599;</a>
    </div>
    <div class="cert-card">
      <div class="cert-provider">Microsoft</div>
      <h3>Microsoft Learn</h3>
      <p>Free learning paths and certifications in Azure, AI, Microsoft 365, and more &#8212; from fundamentals to professional-level credentials.</p>
      <a href="https://learn.microsoft.com" target="_blank" rel="noopener" class="cert-link">learn.microsoft.com &#8599;</a>
    </div>
  </div>
</div>

<!-- IMAGE SECTION -->
<div class="section fade-up">
  <div class="section-label">Where We Are Going</div>
  <h2 class="section-title">The <em>Road</em> Ahead</h2>
  <div class="split">
    <div class="split-text">
      <p class="body-text">
        The old schoolhouse on the hill taught every child in the county to read and write. It did not ask for credentials before it opened its door. It asked only that you show up willing to learn.
      </p>
      <p class="body-text" style="margin-top:1.25rem;">
        That is what TMI is. A community that shows up with you. Every certification earned here is a door opened. Every door opened is a life changed. Every life changed is the mandate fulfilled.
      </p>
    </div>
    <img src="schoolhouse.png" alt="A red schoolhouse on a hill under a bright sky with sun rays breaking through clouds">
  </div>
</div>

<!-- APPLY / CONTACT -->
<div class="contact-section" id="apply">
  <div class="contact-inner">
    <div class="section-label">Join Us</div>
    <h2 class="section-title">Apply <em>Free</em></h2>
    <p class="body-text">
      Tell us where you are. We will meet you there. There is no cost, no obligation, and no judgment. Just community and a path forward.
    </p>
    <!-- Replace YOUR_FORM_ID below with the ID from your free Formspree account at formspree.io -->
    <form action="https://formspree.io/f/YOUR_FORM_ID" method="POST">
      <div class="form-row">
        <div class="form-group">
          <label for="fname">First Name</label>
          <input type="text" id="fname" name="first_name" required placeholder="First">
        </div>
        <div class="form-group">
          <label for="lname">Last Name</label>
          <input type="text" id="lname" name="last_name" required placeholder="Last">
        </div>
      </div>
      <div class="form-group">
        <label for="email">Email Address</label>
        <input type="email" id="email" name="email" required placeholder="you@example.com">
      </div>
      <div class="form-group">
        <label for="situation">Your Situation</label>
        <select id="situation" name="situation">
          <option value="">Select one...</option>
          <option value="recently-displaced">Recently displaced from work</option>
          <option value="long-term-unemployed">Long-term unemployed</option>
          <option value="career-change">Looking to change careers</option>
          <option value="underemployed">Underemployed, seeking advancement</option>
          <option value="other">Other</option>
        </select>
      </div>
      <div class="form-group">
        <label for="support">What Kind of Support Do You Need Most?</label>
        <select id="support" name="support_needed">
          <option value="">Select one...</option>
          <option value="certifications">Help finding and completing certifications</option>
          <option value="job-placement">Job placement and resume help</option>
          <option value="study-support">Study support and accountability</option>
          <option value="emotional-faith">Emotional and faith support</option>
          <option value="all">All of the above</option>
        </select>
      </div>
      <div class="form-group">
        <label for="message">Anything Else You Want Us to Know</label>
        <textarea id="message" name="message" placeholder="Optional &#8212; share as much or as little as you like."></textarea>
      </div>
      <button type="submit" class="form-submit">Submit Application</button>
    </form>
  </div>
</div>

<!-- FOOTER -->
<footer>
  <div class="footer-name">The <em>Thessalonian</em> Mandate Institute</div>
  <div class="footer-mono">TMI &nbsp;&#183;&nbsp; Est. 2026 &nbsp;&#183;&nbsp; Faith-Based</div>
  <p>
    A faith-based workforce support network for displaced workers.<br>
    Rooted in 1 Thessalonians 4:11.<br><br>
    Contact: <a href="mailto:rickeybennett87@gmail.com">rickeybennett87@gmail.com</a>
  </p>
</footer>

<script>
  // Scroll fade-in
  const observer = new IntersectionObserver((entries) => {
    entries.forEach(entry => {
      if (entry.isIntersecting) {
        entry.target.classList.add('visible');
      }
    });
  }, { threshold: 0.1 });

  document.querySelectorAll('.fade-up').forEach(el => observer.observe(el));
</script>

</body>
</html>
HTMLEOF
echo "Done"

