    font-size: 18px;
    line-height: 1.7;
    overflow-x: hidden;
  }

  /* NAV */
  nav {
    position: sticky;
    top: 0;
    z-index: 100;
    background: rgba(26,20,16,0.96);
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0.9rem 2rem;
    gap: 1rem;
    flex-wrap: wrap;
  }

  .nav-brand {
    font-family: 'Cormorant Garamond', serif;
    font-size: 1rem;
    font-weight: 300;
    color: var(--parchment);
    letter-spacing: 0.04em;
    text-decoration: none;
  }

  .nav-brand em { color: var(--gold); font-style: italic; }

  .nav-links {
    display: flex;
    gap: 1.5rem;
    flex-wrap: wrap;
    align-items: center;
  }

  .nav-links a {
    font-family: 'DM Mono', monospace;
    font-size: 0.65rem;
    letter-spacing: 0.16em;
    text-transform: uppercase;
    color: #a09888;
    text-decoration: none;
    transition: color 0.2s;
  }

  .nav-links a:hover { color: var(--gold); }

  .nav-apply {
    font-family: 'DM Mono', monospace;
    font-size: 0.65rem;
    letter-spacing: 0.16em;
    text-transform: uppercase;
    background: var(--gold);
    color: var(--ink);
    padding: 0.5rem 1.2rem;
    text-decoration: none;
    transition: background 0.2s;
  }

  .nav-apply:hover { background: var(--gold-light); }

  /* HERO */
  .hero {
    position: relative;
    min-height: 92vh;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    text-align: center;
    padding: 5rem 2rem;
    overflow: hidden;
  }

  .hero-bg {
    position: absolute;
    inset: 0;
    background-image: url('sky.png');
    background-size: cover;
    background-position: center 30%;
    z-index: 0;
  }

  .hero-bg::after {
    content: '';
    position: absolute;
    inset: 0;
    background: linear-gradient(
      to bottom,
      rgba(245,240,232,0.15) 0%,
      rgba(245,240,232,0.35) 60%,
      rgba(245,240,232,0.92) 100%
    );
  }

  .hero-content {
    position: relative;
    z-index: 1;
    max-width: 780px;
  }

  .hero-eyebrow {
    font-family: 'DM Mono', monospace;
    font-size: 0.72rem;
    letter-spacing: 0.25em;
    text-transform: uppercase;
    color: var(--gold);
    margin-bottom: 1.75rem;
  }

  .hero h1 {
    font-size: clamp(2.2rem, 6vw, 4.2rem);
    font-weight: 300;
    line-height: 1.2;
    color: var(--ink);
    text-shadow: 0 1px 4px rgba(245,240,232,0.6);
  }

  .hero h1 em {
    font-style: italic;
    color: var(--gold);
  }

  .hero h1 .sky-line {
    color: var(--sky);
    display: block;
  }

  .hero-rule {
    width: 48px;
    height: 1px;
    background: var(--gold);
    margin: 2rem auto;
  }

  .hero p {
    font-size: clamp(1rem, 2vw, 1.25rem);
    font-style: italic;
    font-weight: 300;
    color: var(--ash);
    max-width: 560px;
    margin: 0 auto 2.5rem;
    line-height: 1.8;
  }

  .hero-cta {
    display: inline-block;
    font-family: 'DM Mono', monospace;
    font-size: 0.72rem;
    letter-spacing: 0.2em;
    text-transform: uppercase;
    background: var(--ink);
    color: var(--parchment);
    padding: 1rem 2.5rem;
    text-decoration: none;
    transition: background 0.2s;
  }

  .hero-cta:hover { background: var(--gold); color: var(--ink); }

  /* SCRIPTURE BAND */
  .scripture-band {
    background: var(--ink);
    color: var(--parchment);
    text-align: center;
    padding: 3rem 2rem;
  }

  .scripture-band blockquote {
    font-size: clamp(1rem, 2.5vw, 1.4rem);
    font-style: italic;
    font-weight: 300;
    max-width: 700px;
    margin: 0 auto;
    line-height: 1.75;
  }

  .scripture-band cite {
    display: block;
    margin-top: 1rem;
    font-family: 'DM Mono', monospace;
    font-size: 0.68rem;
    letter-spacing: 0.18em;
    text-transform: uppercase;
    font-style: normal;
    color: var(--gold);
  }

  /* SECTIONS */
  .section {
    max-width: 960px;
    margin: 0 auto;
    padding: 5rem 2rem;
    border-bottom: 1px solid var(--rule);
  }

  .section:last-of-type { border-bottom: none; }

  .section-label {
    font-family: 'DM Mono', monospace;
    font-size: 0.68rem;
    letter-spacing: 0.22em;
    text-transform: uppercase;
    color: var(--gold);
    margin-bottom: 1.5rem;
    display: flex;
    align-items: center;
    gap: 1rem;
  }

  .section-label::after {
    content: '';
    flex: 1;
    height: 1px;
    background: var(--rule);
    max-width: 180px;
  }

  .section-title {
    font-size: clamp(1.5rem, 3.5vw, 2.4rem);
    font-weight: 300;
    line-height: 1.3;
    margin-bottom: 1.5rem;
