  .body-text + .body-text { margin-top: 1.25rem; }

  /* IMAGE SPLIT */
  .split {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 3rem;
    align-items: center;
    margin-top: 3rem;
  }

  .split img {
    width: 100%;
    height: 320px;
    object-fit: cover;
    object-position: center;
  }

  .split-text { padding: 1rem 0; }

  /* PILLARS */
  .pillars {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 1.5rem;
    margin-top: 3rem;
  }

  .pillar {
    padding: 2rem 1.5rem;
    border: 1px solid var(--rule);
