    border: none;
    padding: 1rem 2.5rem;
    cursor: pointer;
    transition: background 0.2s;
    margin-top: 0.5rem;
  }

  .form-submit:hover { background: var(--gold-light); }

  /* FOOTER */
  footer {
    background: #0e0c0a;
    color: #6b6460;
    text-align: center;
    padding: 3rem 2rem;
  }

  .footer-name {
    font-family: 'Cormorant Garamond', serif;
    font-size: 1.1rem;
    font-weight: 300;
