    color: var(--parchment);
    margin-bottom: 0.4rem;
  }

  .footer-name em { color: var(--gold); font-style: italic; }

  .footer-mono {
    font-family: 'DM Mono', monospace;
    font-size: 0.62rem;
    letter-spacing: 0.18em;
    text-transform: uppercase;
    color: var(--gold);
    margin-bottom: 1.5rem;
  }

